package com.pipican.client.boss;
import com.pipican.Pipican;import com.pipican.boss.DurmagonEntity;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;import net.minecraft.resources.Identifier;import net.minecraft.util.Mth;
/** Runic core and hammer windups for the preserved Durmagon geometry. */
public final class DurmagonRenderer extends MobRenderer<DurmagonEntity,DurmagonRenderer.State,DurmagonRenderer.Model>{public DurmagonRenderer(EntityRendererProvider.Context c){super(c,new Model(BossGeometry.load("durmagon_runic_titan")),1.1f);}public static final class State extends LivingEntityRenderState{int phase,action;float remaining,hurt;}@Override public State createRenderState(){return new State();}@Override public Identifier getTextureLocation(State s){return Pipican.id("textures/entity/boss/durmagon_"+(s.phase==2?"awakened":"runic")+".png");}@Override public void extractRenderState(DurmagonEntity e,State s,float p){super.extractRenderState(e,s,p);s.phase=e.phase();s.action=e.durmagonAction();s.remaining=Math.max(0,e.abilityTicksRemaining()-p);s.hurt=e.hurtTime-p;}@Override protected net.minecraft.world.phys.AABB getBoundingBoxForCulling(DurmagonEntity e){return super.getBoundingBoxForCulling(e).inflate(1.5);}
 static final class Model extends EntityModel<State>{private final ModelPart body,head,leftArm,rightArm,leftLeg,rightLeg,core,leftShoulder,rightShoulder;Model(ModelPart r){super(r);var root=r.getChild("root");body=root.getChild("body");head=body.getChild("head");leftArm=body.getChild("left_arm");rightArm=body.getChild("right_arm");leftLeg=root.getChild("left_leg");rightLeg=root.getChild("right_leg");core=body.getChild("chest_core");leftShoulder=body.getChild("left_shoulder");rightShoulder=body.getChild("right_shoulder");}@Override public void setupAnim(State s){super.setupAnim(s);float gait=Mth.clamp(s.walkAnimationSpeed,0,1),pulse=Mth.sin(s.ageInTicks*.16f),tell=1-Mth.clamp(s.remaining/60f,0,1);head.yRot=Mth.clamp(s.yRot,-30,30)*Mth.DEG_TO_RAD;head.xRot=Mth.clamp(s.xRot,-10,10)*Mth.DEG_TO_RAD;leftArm.xRot=Mth.cos(s.ageInTicks*.48f)*.36f*gait;rightArm.xRot=Mth.cos(s.ageInTicks*.48f+(float)Math.PI)*.36f*gait;leftLeg.xRot=Mth.cos(s.ageInTicks*.48f+(float)Math.PI)*.42f*gait;rightLeg.xRot=Mth.cos(s.ageInTicks*.48f)*.42f*gait;core.xRot=pulse*.025f;leftShoulder.zRot=-.04f+pulse*.02f;rightShoulder.zRot=.04f-pulse*.02f;switch(s.action){case 1->{rightArm.xRot=-.8f*tell;}case 2->{leftArm.xRot=-.3f*tell;rightArm.xRot=-.65f*tell;core.xRot=-.1f*tell;}case 3->{rightArm.xRot=-1.1f*tell;body.xRot=.04f*tell;}case 4->{rightArm.xRot=-1.35f*tell;body.xRot=.12f*tell;core.xRot=.14f*tell;}case 5->{body.xRot=.1f;leftShoulder.zRot=-.18f;rightShoulder.zRot=.18f;}case 6->{leftArm.xRot=-.2f;rightArm.xRot=-.25f;core.xRot=-.12f;}default->{}}if(s.phase==2)core.xRot+=pulse*.075f;if(s.hurt>0)body.zRot=.035f*Mth.sin(s.hurt*1.4f);if(s.deathTime>0)body.xRot=.65f;}}
}
